        .text-justify { text-align: justify; }

        .newspaper-layout {
            width: 100%;
            display: table;
            table-layout: fixed;
        }
        .column {
            display: table-cell;
            vertical-align: top;
            padding-right: 10px;
            padding-left: 10px;
        }
        .column:first-child { padding-left: 0; }
        .column:last-child { padding-right: 0; }

        .col-1 { width: 31%; }
